export interface Reader {                    // erased: no state, no runtime object
  read(n: number): Promise<Uint8Array>;
}

export class FileReader implements Reader {  // checked at the declaration site
  constructor(private readonly path: string) {}
  async read(n: number): Promise<Uint8Array> { return readChunk(this.path, n); }
}
export abstract class Closeable {            // runtime contract + protected state
  protected open = true;
  abstract close(): void;
}
